def grep(pattern, flags, files):
    ignore_case = '-i' in flags
    invert_match = '-v' in flags
    whole_line = '-x' in flags
    only_filenames = '-l' in flags
    show_line_numbers = '-n' in flags
    multiple_files = len(files) > 1

    def matches(line):
        candidate = line.rstrip('\n')
        if ignore_case:
            candidate_cmp = candidate.lower()
            pattern_cmp = pattern.lower()
        else:
            candidate_cmp = candidate
            pattern_cmp = pattern

        if whole_line:
            matched = candidate_cmp == pattern_cmp
        else:
            matched = pattern_cmp in candidate_cmp

        return not matched if invert_match else matched

    results = []
    for filename in files:
        found_in_file = False
        with open(filename, 'r', encoding='utf-8') as f:
            for lineno, line in enumerate(f, start=1):
                if matches(line):
                    found_in_file = True
                    if only_filenames:
                        break

                    parts = []
                    if multiple_files:
                        parts.append(f"{filename}:")
                    if show_line_numbers:
                        parts.append(f"{lineno}:")
                    parts.append(line)
                    results.append(''.join(parts))

        if only_filenames and found_in_file:
            results.append(filename)

    return ''.join(results)

