    def __init__(self, database=None):
        self._db = {}
        if database:
            for user in database.get('users', []):
                name = user['name']
                owes = {k: float(v) for k, v in user.get('owes', {}).items()}
                owed_by = {k: float(v) for k, v in user.get('owed_by', {}).items()}
                self._db[name] = {'owes': owes, 'owed_by': owed_by}

    def get(self, url, payload=None):
        if url != '/users':
            return None

        if payload and 'users' in payload:
            names = sorted(payload['users'])
        else:
            names = sorted(self._db)

        return {'users': [self._user_object(name) for name in names if name in self._db]}

    def post(self, url, payload=None):
        if url == '/add':
            name = payload['user']
            self._db[name] = {'owes': {}, 'owed_by': {}}
            return self._user_object(name)

        if url == '/iou':
            lender = payload['lender']
            borrower = payload['borrower']
            amount = float(payload['amount'])

            self._apply_iou(lender, borrower, amount)
            return {'users': [self._user_object(name) for name in sorted([lender, borrower])]}

        return None

    def _apply_iou(self, lender, borrower, amount):
        lender_owes = self._db[lender]['owes']
        lender_owed_by = self._db[lender]['owed_by']
        borrower_owes = self._db[borrower]['owes']
        borrower_owed_by = self._db[borrower]['owed_by']

        reverse = borrower_owes.get(lender, 0.0)
        if reverse > 0:
            if reverse > amount:
                borrower_owes[lender] = reverse - amount
                lender_owed_by[borrower] = borrower_owed_by.get(lender, 0.0) + amount
                return
            elif reverse == amount:
                del borrower_owes[lender]
                borrower_owed_by.pop(lender, None)
                lender_owes.pop(borrower, None)
                lender_owed_by.pop(borrower, None)
                return
            else:
                amount -= reverse
                del borrower_owes[lender]
                borrower_owed_by.pop(lender, None)
                lender_owed_by.pop(borrower, None)

        lender_owed_by[borrower] = lender_owed_by.get(borrower, 0.0) + amount
        borrower_owes[lender] = borrower_owes.get(lender, 0.0) + amount

    def _user_object(self, name):
        owes = dict(sorted(self._db[name]['owes'].items()))
        owed_by = dict(sorted(self._db[name]['owed_by'].items()))
        balance = sum(owed_by.values()) - sum(owes.values())
        return {
            'name': name,
            'owes': owes,
            'owed_by': owed_by,
            'balance': balance,
        }

