def can_chain(dominoes):
    if not dominoes:
        return True

    degree = {}
    adjacency = {}

    for a, b in dominoes:
        degree[a] = degree.get(a, 0) + 1
        degree[b] = degree.get(b, 0) + 1
        adjacency.setdefault(a, set()).add(b)
        adjacency.setdefault(b, set()).add(a)

    active_vertices = [v for v, d in degree.items() if d > 0]
    if not active_vertices:
        return True

    start = active_vertices[0]
    stack = [start]
    visited = set()

    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        for n in adjacency.get(v, ()):
            if n not in visited:
                stack.append(n)

    for v in active_vertices:
        if v not in visited:
            return False
        if degree[v] % 2 != 0:
            return False

    return True

def can_chain(dominoes):
    if not dominoes:
        return []

    adjacency = {}
    degree = {}

    for i, (a, b) in enumerate(dominoes):
        degree[a] = degree.get(a, 0) + 1
        degree[b] = degree.get(b, 0) + 1
        adjacency.setdefault(a, []).append((b, i))
        adjacency.setdefault(b, []).append((a, i))

    active = [v for v in degree if degree[v] > 0]
    start = active[0]

    stack = [start]
    visited = set()
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        for n, _ in adjacency.get(v, []):
            if n not in visited:
                stack.append(n)

    for v in active:
        if v not in visited or degree[v] % 2 != 0:
            return None

    used = [False] * len(dominoes)
    chain_vertices = [start]
    result = []

    def dfs(v):
        if len(result) == len(dominoes):
            return v == start

        for n, idx in adjacency.get(v, []):
            if used[idx]:
                continue
            used[idx] = True
            result.append(dominoes[idx] if dominoes[idx][0] == v else (dominoes[idx][1], dominoes[idx][0]))
            chain_vertices.append(n)
            if dfs(n):
                return True
            chain_vertices.pop()
            result.pop()
            used[idx] = False

        return False

    if dfs(start):
        return result
    return None

def proverb(*items, qualifier=None):
    if not items:
        return ""

    lines = [
        f"For want of a {current} the {next_item} was lost."
        for current, next_item in zip(items, items[1:])
    ]

    final_item = qualifier or items[0]
    lines.append(f"And all for the want of a {final_item}.")

    return "\n".join(lines)

